100 *
(
    sum(
        rate(
            http_server_request_duration_seconds_count{
                exported_job="20h-project",
                http_response_status_code=~"5.."
            }[$__rate_interval]
        )
    )
    or vector(0)
)
/
clamp_min(
    sum(
        rate(
            http_server_request_duration_seconds_count{
                exported_job="20h-project"
            }[$__rate_interval]
        )
    ),
    0.000000001
)

